{'tool_name': 'filter_json_with_strategy', 'arguments': {'input_json_path': '../ml_oxides_trial_7/polymorph_data/TiO2_polymorphs.json', 'output_json_path': 'temp_consolidated.json', 'custom_code': '
import json
import glob
import os

# Get all polymorph files from trial_7
polymorph_dir = "../ml_oxides_trial_7/polymorph_data"
all_files = glob.glob(os.path.join(polymorph_dir, "*_polymorphs.json"))

# Consolidate all data
filtered_data = []
for file_path in all_files:
    try:
        with open(file_path, 'r') as f:
            polymorphs = json.load(f)
            if isinstance(polymorphs, list):
                filtered_data.extend(polymorphs)
    except Exception as e:
